WITH eu AS (SELECT e.id AS executivo_id, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')) UPDATE pedidos SET catalogo = CAST(:catalogo AS JSONB), resumo = CAST(:resumo AS JSONB), produtos = CAST(:produtos AS INTEGER), preco = :preco, curadoria_fim = now(), atualizado_em = now() FROM eu WHERE pedidos.pedido_id = :pedido_id AND pedidos.status = 'curadoria' AND pedidos.portal_id IS NULL AND (eu.admin OR pedidos.executivo_id = eu.executivo_id) RETURNING pedidos.pedido_id, pedidos.produtos, pedidos.preco
